class Pool:
    def __init__(self): self.n = 0
    def new(self, k=1):
        r = list(range(self.n + 1, self.n + 1 + k)); self.n += k; return r


def gen_key(rnd, N, A, K):
    """Distinct read positions K (letters 0..A-1 -> k[a]); class map; class shuffles with no doubles."""
    k = rnd.sample(range(N), A); Kset = set(k)
    cls = [rnd.randrange(K) for _ in range(A)]
    for c in range(K): cls[c] = c                      # every class non-empty
    outside = [p for p in range(N) if p not in Kset]
    sig = []
    for c in range(K):
        inv = [None] * N                               # inv[q] = s_c^-1(q)
        mine = [k[a] for a in range(A) if cls[a] == c]
        img = rnd.sample(outside, len(mine))
        for q, v in zip(mine, img): inv[q] = v
        rest_q = [q for q in range(N) if inv[q] is None]
        rest_v = [v for v in range(N) if v not in set(img)]
        rnd.shuffle(rest_v)
        for q, v in zip(rest_q, rest_v): inv[q] = v
        s = [None] * N
        for q, v in enumerate(inv): s[v] = q
        sig.append(s)
    return k, cls, sig


def encrypt(key, pt, N, D0=None):
    k, cls, sig = key
    D = list(range(N)) if D0 is None else list(D0)
    out = []
    for a in pt:
        out.append(D[k[a]])
        s = sig[cls[a]]
        D = [D[s[p]] for p in range(N)]
    return out


def make_texts(rnd, lang, A, lens):
    """Plaintexts as letter indices 0..A-1: corpus excerpts, characters folded onto A letters by frequency rank."""
    if lang == 'fi':
        c = CORPUS_FI
    else:
        c = open(os.path.join(HERE, 'corpus_%s.txt' % lang), encoding='utf-8').read()
    from collections import Counter
    rank = {ch: i for i, (ch, _) in enumerate(Counter(c).most_common())}
    texts = []
    for L in lens:
        s = rnd.randrange(len(c) - L)
        texts.append([rank[ch] % A for ch in c[s:s + L]])
    return texts


def encode(cts, pts, cls, N, A, K, Dmax, anchor=True, solver='cadical153', prefix=None, symbreak=False, longeq=False, onehot=False,
           anchor_all=False, old_anchor=False):
    """cts/pts: per-message ciphertext symbols and plaintext letter indices (0..A-1, equal index = same letter).
    cls: class of each letter, or None to let the solver choose (K must be 2).  A crib may cover a different
    prefix of each message (ciphertext is cut to the plaintext length); empty messages are skipped."""
    if prefix:   # crib attack: only the first `prefix` letters of every message are known
        cts = [ct[:prefix] for ct in cts]; pts = [pt[:prefix] for pt in pts]
    keep = [i for i, pt in enumerate(pts) if len(pt) > 0]
    cts = [cts[i][:len(pts[i])] for i in keep]; pts = [pts[i] for i in keep]
    unknown = cls is None
    if unknown and K != 2: raise ValueError('unknown classes are supported for K=2 only')
    if unknown and onehot: raise ValueError('onehot encoding needs known classes')
    B = max(1, (N - 1).bit_length())
    vp = Pool()
    S = Solver(name=solver)
    ncl = [0]
    def add(cl): S.add_clause(cl); ncl[0] += 1
    # class shuffles: binary bits + one-hot channel
    sb = [[vp.new(B) for p in range(N)] for c in range(K)]
    sx = [[vp.new(N) for p in range(N)] for c in range(K)]
    for c in range(K):
        for p in range(N):
            add(sx[c][p])                                     # at least one value
            for q in range(N):
                x = sx[c][p][q]
                for j in range(B):
                    add([-x, sb[c][p][j] if (q >> j) & 1 else -sb[c][p][j]])
        for q in range(N):                                    # each value used at most once (column AMO)
            enc = CardEnc.atmost([sx[c][p][q] for p in range(N)], 1, top_id=vp.n, encoding=EncType.seqcounter)
            for cl in enc.clauses: add(cl)
            vp.n = max(vp.n, enc.nv)
    if symbreak:
        # Non-read positions (>= A) can be relabelled freely.  Canonical labelling (fresh labels handed
        # out in order while scanning s_0(0), s_0(1), ...) implies s_0(i) <= A + i.
        for i in range(N):
            for q in range(A + i + 1, N):
                add([-sx[0][i][q]])
    cb = None
    if unknown:
        cb = vp.new(A); add([-cb[0]])                      # class bit per letter; class symmetry: letter 0 in class 0
    def classes_of(a):
        """[(class, selector)]: the selector literals are false exactly when letter a has that class"""
        if not unknown: return [(cls[a], [])]
        return [(0, [cb[a]]), (1, [-cb[a]])]
    def mux(prev, a, z):
        for c, sel in classes_of(a):
            for p in range(N):
                cond = [prev[j] if not (p >> j) & 1 else -prev[j] for j in range(B)]   # false exactly when prev == p
                for j in range(B):
                    add(sel + cond + [-z[j], sb[c][p][j]]); add(sel + cond + [z[j], -sb[c][p][j]])
    def eq_const(bits, v):  # bits == v (unit clauses)
        for j in range(B):
            add([bits[j] if (v >> j) & 1 else -bits[j]])
    def neq_const(bits, v):
        add([-bits[j] if (v >> j) & 1 else bits[j] for j in range(B)])
    Pv = []          # per message: dict (t,d) -> bit vars (t 0-based)
    for m, (ct, pt) in enumerate(zip(cts, pts)):
        L = len(ct); P = {}; Y = {}
        for d in range(1, Dmax + 1):
            for t in range(L - d):
                c = None if unknown else cls[pt[t]]
                if d == 1 and not unknown:
                    P[(t, 1)] = sb[c][pt[t + 1]]              # alias: s_c[k_{a_{t+1}}]
                    if onehot: Y[(t, 1)] = sx[c][pt[t + 1]]
                elif d == 1:
                    z = vp.new(B)
                    for c2, sel in classes_of(pt[t]):
                        for j in range(B):
                            add(sel + [-z[j], sb[c2][pt[t + 1]][j]]); add(sel + [z[j], -sb[c2][pt[t + 1]][j]])
                    P[(t, 1)] = z
                elif onehot:
                    z = vp.new(B); y = vp.new(N); yp = Y[(t + 1, d - 1)]
                    for p in range(N):
                        for j in range(B):
                            add([-yp[p], -z[j], sb[c][p][j]]); add([-yp[p], z[j], -sb[c][p][j]])
                    for q in range(N):                        # channel y <-> z
                        for j in range(B): add([-y[q], z[j] if (q >> j) & 1 else -z[j]])
                        add([y[q]] + [-z[j] if (q >> j) & 1 else z[j] for j in range(B)])
                    P[(t, d)] = z; Y[(t, d)] = y
                else:
                    z = vp.new(B); mux(P[(t + 1, d - 1)], pt[t], z)
                    P[(t, d)] = z
                if ct[t] == ct[t + d]: eq_const(P[(t, d)], pt[t])
                else: neq_const(P[(t, d)], pt[t])
        if longeq:   # long-range repeats (d > Dmax): build only the diagonal chains they need
            def getP(t, d):
                if (t, d) in P: return P[(t, d)]
                prev = getP(t + 1, d - 1); z = vp.new(B)
                mux(prev, pt[t], z)
                P[(t, d)] = z
                if ct[t] == ct[t + d]: eq_const(z, pt[t])
                else: neq_const(z, pt[t])
                return z
            for d in range(Dmax + 1, L):
                for t in range(L - d):
                    if ct[t] == ct[t + d]:
                        getP(t, d)
        Pv.append(P)
    def chain(m, t, d):
        """P(t,d) of message m, building the diagonal chain down to the window if needed."""
        P = Pv[m]
        if (t, d) in P: return P[(t, d)]
        ct, pt = cts[m], pts[m]
        z = vp.new(B); mux(chain(m, t + 1, d - 1), pt[t], z)
        P[(t, d)] = z
        if ct[t] == ct[t + d]: eq_const(z, pt[t])
        else: neq_const(z, pt[t])
        return z
    if anchor and old_anchor:   # (old) pairwise equal/different constraints between anchored values
        vals = []
        for m, (ct, pt) in enumerate(zip(cts, pts)):
            vals.append((ct[0], ('c', pt[0])))
            for d in range(1, min(Dmax, len(ct) - 1) + 1):
                vals.append((ct[d], ('v', Pv[m][(0, d)])))
        for (x1, v1), (x2, v2) in itertools.combinations(vals, 2):
            if v1[0] == 'c' and v2[0] == 'c':
                continue
            if v1[0] == 'c': v1, v2 = v2, v1
            b1 = v1[1]
            if v2[0] == 'c':
                if x1 == x2: eq_const(b1, v2[1])
                else: neq_const(b1, v2[1])
            else:
                b2 = v2[1]
                if x1 == x2:
                    for j in range(B):
                        add([-b1[j], b2[j]]); add([b1[j], -b2[j]])
                else:
                    u = vp.new(B)
                    for j in range(B):   # u_j -> b1_j xor b2_j
                        add([-u[j], b1[j], b2[j]]); add([-u[j], -b1[j], -b2[j]])
                    add(u)
    elif anchor:
        # All messages start from the same deck D0, so every card x has ONE starting position pos(x), and
        # different cards have different starting positions (all-different via one-hot + at-most-one per slot).
        # P(0,d) of each message = pos(card read at step d).
        vals = []
        for m, (ct, pt) in enumerate(zip(cts, pts)):
            vals.append((ct[0], ('c', pt[0])))
            dm = len(ct) - 1 if anchor_all else min(Dmax, len(ct) - 1)
            for d in range(1, dm + 1):
                vals.append((ct[d], ('v', chain(m, 0, d))))
        cards = sorted(set(x for x, _ in vals))
        ph, pb = {}, {}
        for x in cards:
            ph[x] = vp.new(N); pb[x] = vp.new(B)
            add(ph[x])
            for q in range(N):
                for j in range(B): add([-ph[x][q], pb[x][j] if (q >> j) & 1 else -pb[x][j]])
                add([ph[x][q]] + [-pb[x][j] if (q >> j) & 1 else pb[x][j] for j in range(B)])
        for q in range(N):
            if len(cards) > 1:
                enc = CardEnc.atmost([ph[x][q] for x in cards], 1, top_id=vp.n, encoding=EncType.seqcounter)
                for cl in enc.clauses: add(cl)
                vp.n = max(vp.n, enc.nv)
        for x, v in vals:
            if v[0] == 'c':
                add([ph[x][v[1]]])
            else:
                for j in range(B):
                    add([-v[1][j], pb[x][j]]); add([v[1][j], -pb[x][j]])
    encode.class_vars = cb
    return S, sb, ncl[0], vp.n, B


def decode_sigma(model, sb, N, K, B):
    ms = set(l for l in model if l > 0)
    return [[sum(1 << j for j in range(B) if sb[c][p][j] in ms) for p in range(N)] for c in range(K)]


def check_full(sig, cts, pts, cls, N):
    """Using recovered shuffles (with k_a = a), count CT-equality mismatches at ALL distances within messages."""
    bad = tot = 0
    for ct, pt in zip(cts, pts):
        L = len(ct)
        D = list(range(N)); orig = []          # deck labelled by original (D0) position
        for a in pt:
            orig.append(D[a])
            s = sig[cls[a]]
            D = [D[s[p]] for p in range(N)]
        for i in range(L):
            for j in range(i + 1, L):
                tot += 1
                bad += (orig[i] == orig[j]) != (ct[i] == ct[j])
    return bad, tot


def solve(S, timeout=None):
    """Run the solver; True / False.  pysat's CaDiCaL ignores interrupts, so a timeout is a watchdog that
    ends the whole process with exit code 3."""
    timer = None
    if timeout:
        def kill():
            print(f'TIMEOUT after {timeout:.0f}s (no answer)', flush=True); os._exit(3)
        timer = threading.Timer(timeout, kill); timer.daemon = True; timer.start()
    res = S.solve()
    if timer: timer.cancel()
    return res


def run_synth(a):
    lens = [len(m) for m in MSGS]
    rnd = random.Random(a.seed)
    key = gen_key(rnd, a.N, a.A, a.K)
    pts = make_texts(rnd, a.lang, a.A, lens)
    D0 = list(range(a.N)); rnd.shuffle(D0)
    cts = [encrypt(key, pt, a.N, D0) for pt in pts]
    dbl = sum(1 for ct in cts for i in range(len(ct) - 1) if ct[i] == ct[i + 1])
    if a.mode == 'wrong':          # wrong plaintext guess: fresh excerpts, same lengths -> expect UNSAT
        pts = make_texts(random.Random(a.seed + 1000), a.lang, a.A, lens)
    elif a.mode.startswith('mut'):  # change a fraction of letters, e.g. mut0.05
        f = float(a.mode[3:]); r2 = random.Random(a.seed + 2000)
        pts = [[(x if r2.random() > f else r2.randrange(a.A)) for x in pt] for pt in pts]
    t0 = time.time()
    S, sb, ncl, nv, B = encode(cts, pts, None if a.unknown_classes else key[1], a.N, a.A, a.K, a.dmax,
                               prefix=a.prefix, symbreak=not a.no_symbreak, longeq=a.long, onehot=a.onehot, solver=a.solver,
                               anchor_all=a.anchor_all, old_anchor=a.old_anchor)
    t1 = time.time()
    res = solve(S, a.timeout); t2 = time.time()
    msg = (f'synth N={a.N} A={a.A} K={a.K} dmax={a.dmax} seed={a.seed} lang={a.lang} mode={a.mode} prefix={a.prefix} '
           f'unknown_classes={a.unknown_classes} long={a.long} doubles={dbl} vars={nv} clauses={ncl} '
           f'encode={t1-t0:.1f}s solve={t2-t1:.1f}s result={"SAT" if res else "UNSAT"}')
    if res:
        model = S.get_model()
        sig = decode_sigma(model, sb, a.N, a.K, B)
        cls = key[1]
        if a.unknown_classes:
            ms = set(l for l in model if l > 0)
            cls = [1 if v in ms else 0 for v in encode.class_vars]
        bad, tot = check_full(sig, cts, pts, cls, a.N)
        msg += f' full-message check: {bad} wrong of {tot} symbol pairs'
    print(msg, flush=True)


def read_crib(path, names):
    crib = {}
    for ln in open(path, encoding='utf-8').read().split('\n'):
        ln = ln.rstrip('\r')
        if not ln.strip() or ln.lstrip().startswith('#'): continue
        name, sep, text = ln.partition(':')
        name = name.strip().upper()
        if not sep or name not in names:
            raise SystemExit(f'bad crib line {ln!r}: expected "NAME: text" with NAME one of {names}')
        if text.startswith(' '): text = text[1:]          # "E1: TEXT" -> "TEXT" (other spaces are letters)
        crib[name] = text
    return crib


def run_eyes(a):
    """Test a crib (plaintext guess) against the real eye messages under class-XGAK."""
    msgs = MSGS
    if a.ct:   # alternative ciphertext (same format as data/eyes_ascii32.txt: 9 lines, value = ord(c) - 32)
        msgs = [[ord(ch) - 32 for ch in l.rstrip('\r\n')] for l in open(a.ct, encoding='utf-8') if l.strip('\r\n')]
        assert len(msgs) == 9, 'ciphertext file must have 9 lines'
    crib = read_crib(a.crib, NAMES)
    off = 1 if a.skip_label else 0
    alphabet = sorted(set(''.join(crib.values())))
    idx = {ch: i for i, ch in enumerate(alphabet)}
    A = len(alphabet)
    if A > 83: raise SystemExit('more than 83 distinct letters')
    cts, pts = [], []
    for name, m in zip(NAMES, msgs):
        ct = m[off:]; text = crib.get(name, '')
        if len(text) > len(ct): raise SystemExit(f'crib for {name} is longer than the message ({len(ct)} symbols)')
        cts.append(ct[:len(text)]); pts.append([idx[ch] for ch in text])
    cls = None
    if a.classes:
        groups = a.classes.split('|')
        if len(groups) != a.K: raise SystemExit('--classes needs exactly K groups separated by |')
        cls = []
        for ch in alphabet:
            g = [i for i, grp in enumerate(groups) if ch in grp]
            cls.append(g[0] if g else len(groups) - 1)       # letters not listed go to the last group
    elif a.K != 2:
        raise SystemExit('without --classes the solver chooses the groups, which needs K=2')
    used = sum(len(p) for p in pts)
    print(f'crib covers {used} symbols in {sum(1 for p in pts if p)} messages; {A} distinct letters; '
          f'groups {"given" if cls else "chosen by the solver"}; K={a.K}; deck of {a.N} cards', flush=True)
    t0 = time.time()
    S, sb, ncl, nv, B = encode(cts, pts, cls, a.N, A, a.K, a.dmax, symbreak=not a.no_symbreak, longeq=a.long, solver=a.solver,
                               anchor_all=a.anchor_all, old_anchor=a.old_anchor)
    t1 = time.time()
    res = solve(S, a.timeout); t2 = time.time()
    print(f'encode {t1-t0:.1f}s, solve {t2-t1:.1f}s, {nv} variables, {ncl} clauses', flush=True)
    if res:
        print('CONSISTENT: some class-XGAK key produces exactly these eye symbols from this crib.')
        if cls is None:
            ms = set(l for l in S.get_model() if l > 0)
            g = [''.join(ch for ch, v in zip(alphabet, encode.class_vars) if (v in ms) == bool(k)) for k in (0, 1)]
            print(f'  one grouping that works: {g[0]!r} | {g[1]!r}')
        print('  Note: short cribs are easy to satisfy. A result only means something once random guesses of the'
              ' same shape fail; run a control (e.g. the same crib with its letters shuffled).')
    else:
        print('IMPOSSIBLE: no class-XGAK key fits this crib (assuming all messages start from the same deck'
              + (' and all first letters share a group' if a.skip_label else '') + ').')


if __name__ == '__main__':
    import argparse
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    sub = ap.add_subparsers(dest='cmd', required=True)
    common = argparse.ArgumentParser(add_help=False)
    common.add_argument('--dmax', type=int, default=16, help='encode all repeats up to this distance (default 16)')
    common.add_argument('--long', action='store_true', help='also encode every longer-distance repeat (faster on big decks)')
    common.add_argument('--no-symbreak', action='store_true', help='disable symmetry breaking')
    common.add_argument('--timeout', type=float, default=None, help='give up after this many seconds')
    common.add_argument('--anchor-all', action='store_true', help='tie every crib position to the shared starting deck (stronger, bigger)')
    common.add_argument('--old-anchor', action='store_true', help='previous pairwise anchoring encoding (for comparison)')
    common.add_argument('--solver', default='cadical153', help='pysat solver name (cadical153, cadical195, glucose4, maplechrono, lingeling, minisat22)')
    sy = sub.add_parser('synth', parents=[common], help='known-plaintext recovery on fake messages (eye lengths)')
    sy.add_argument('N', type=int, help='deck size (83 for the eyes)')
    sy.add_argument('A', type=int, help='number of plaintext letters')
    sy.add_argument('--K', type=int, default=2, help='number of letter groups (default 2)')
    sy.add_argument('--seed', type=int, default=1)
    sy.add_argument('--lang', default='fi', help='corpus for the fake text: fi (built in) or X for a file corpus_X.txt next to this script')
    sy.add_argument('--mode', default='true', help='true | wrong (wrong plaintext: expect UNSAT) | mutF (change fraction F of letters)')
    sy.add_argument('--prefix', type=int, default=None, help='only the first PREFIX letters of each message are known (crib)')
    sy.add_argument('--unknown-classes', action='store_true', help="don't tell the solver which letters share a shuffle (K=2)")
    sy.add_argument('--onehot', action='store_true', help='alternative encoding (needs known classes)')
    ey = sub.add_parser('eyes', parents=[common], help='test a plaintext guess (crib) against the real eye messages')
    ey.add_argument('crib', help='text file with lines "E1: SOMETEXT" (names E1 W1 E2 W2 E3 W3 E4 W4 E5); same character = same letter')
    ey.add_argument('--K', type=int, default=2)
    ey.add_argument('--N', type=int, default=83, help='deck size (83 for the eyes; smaller only for --ct experiments)')
    ey.add_argument('--classes', default=None, help='letter groups, e.g. "0123456789|ABCDEFG..." (default: solver chooses, K=2)')
    ey.add_argument('--skip-label', action='store_true', help='crib starts at the 2nd symbol (assumes all first letters share a group)')
    ey.add_argument('--ct', default=None, help='use this ciphertext file (eyes_ascii32 format) instead of the real eyes, e.g. for controls')
    a = ap.parse_args()
    a.onehot = getattr(a, 'onehot', False)
    if a.cmd == 'synth': run_synth(a)
    else: run_eyes(a)
